fn count_uppercase(text: &Vec<char>) -> u64 {
    // Base case: if the vector is empty, return 0
    if text.is_empty() {
        return 0;
    }

    // Recursive case: check the first character and count the rest
    let first_char = text[0];
    let count_rest = count_uppercase(&text[1..].to_vec()); // Recursively count the rest of the characters

    // Check if the first character is an uppercase ASCII letter
    if first_char >= 'A' && first_char <= 'Z' {
        count_rest + 1 // Include this character in the count
    } else {
        count_rest // Do not include this character
    }
}